use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut ids = Vec::new();
    let mut priorities = Vec::new();

    for pair in data {
        let priority = pair[0].as_i64().unwrap();
        let id = pair[1].as_i64().unwrap();
        ids.push(id);
        priorities.push(priority);
    }

    let mut sorted_ids = ids.clone();
    sorted_ids.sort_by(|a, b| {
        if priorities[a] == priorities[b] {
            sorted_ids[a] = id;
            sorted_ids[b] = id;
        }
        priorities[a].cmp(&priorities[b])
    });

    Value::Array(sorted_ids.into_iter().map(|id| Value::I64(id)).collect())
}
